// Full-page screenshots of the Book 5 notes via CDP (mirrors the repo's Chrome test harness).
// Usage: node /tmp/p2n-shot.mjs <outDir> <baseUrl> [page ...]
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";
import { createServer } from "node:net";

const [outDir, baseUrl, ...pagesArg] = process.argv.slice(2);
const pages = pagesArg.length ? pagesArg : [
  "book5/index.html",
  "book5/ch01-radiation-and-radioactivity/index.html",
  "book5/ch01-radiation-and-radioactivity/25-1.html",
  "book5/ch01-radiation-and-radioactivity/25-2.html",
  "book5/ch01-radiation-and-radioactivity/25-3.html",
  "book5/ch01-radiation-and-radioactivity/summary.html",
  "book5/ch02-rate-of-decay-and-uses-of-radionuclides/index.html",
  "book5/ch02-rate-of-decay-and-uses-of-radionuclides/26-1.html",
  "book5/ch02-rate-of-decay-and-uses-of-radionuclides/26-2.html",
  "book5/ch02-rate-of-decay-and-uses-of-radionuclides/26-3.html",
  "book5/ch02-rate-of-decay-and-uses-of-radionuclides/summary.html"
];
const chromePath = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
fs.mkdirSync(outDir, { recursive: true });

function nameFor(p) {
  return p.replace(/^book5\//, "").replace(/ch01-[^/]+/, "ch1").replace(/ch02-[^/]+/, "ch2").replace(/\//g, "-").replace(/\.html$/, "");
}

async function freePort() {
  return new Promise((resolve, reject) => {
    const s = createServer();
    s.listen(0, "127.0.0.1", () => { const { port } = s.address(); s.close((e) => (e ? reject(e) : resolve(port))); });
    s.on("error", reject);
  });
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const profile = fs.mkdtempSync(path.join(os.tmpdir(), "p2n-shot-"));
const port = await freePort();
const chrome = spawn(chromePath, [
  "--headless=new", "--use-angle=swiftshader", "--no-first-run", "--no-default-browser-check",
  "--disable-extensions", "--disable-background-timer-throttling", "--disable-renderer-backgrounding",
  "--remote-debugging-port=" + port, "--user-data-dir=" + profile, "--window-size=1280,900", "about:blank"
], { stdio: "ignore" });

let target;
for (let i = 0; i < 100 && !target; i++) {
  try {
    const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = list.find((t) => t.type === "page" && t.webSocketDebuggerUrl);
  } catch (_) { /* retry */ }
  if (!target) await sleep(150);
}
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.addEventListener("open", res, { once: true }); ws.addEventListener("error", rej, { once: true }); });
let nextId = 1; const pending = new Map();
ws.addEventListener("message", (ev) => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(m.error.message)) : p.resolve(m.result); } });
const send = (method, params = {}) => new Promise((resolve, reject) => { const id = nextId++; pending.set(id, { resolve, reject }); ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (pending.has(id)) { pending.delete(id); reject(new Error(method + " timeout")); } }, 30000); });
const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result.value;

await send("Page.enable"); await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });

for (const p of pages) {
  const url = baseUrl.replace(/\/$/, "") + "/" + p + "?_=" + Date.now();
  await send("Page.navigate", { url });
  await sleep(2500);
  const h = await evaluate("Math.min(document.documentElement.scrollHeight, 16000)");
  await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: h, deviceScaleFactor: 1, mobile: false });
  await sleep(600);
  const shot = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true });
  const file = path.join(outDir, nameFor(p) + ".png");
  fs.writeFileSync(file, Buffer.from(shot.data, "base64"));
  console.log(nameFor(p), h + "px", fs.statSync(file).size);
  await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
}
ws.close(); chrome.kill("SIGKILL"); await sleep(200);
fs.rmSync(profile, { recursive: true, force: true });

/* Book 5 notes: one stylesheet for the picker, both chapters and the summaries.
   Document look: flat paper, serif headings, numbered sections, captioned figures,
   definition / formula / worked-example / exam-tip blocks, explained concept checks. */

:root {
  --paper: #f7f3eb;
  --panel: #fffdf8;
  --ink: #1b2129;
  --muted: #5d6673;
  --rule: #d9d2c4;
  --rule-soft: #e9e3d6;
  --accent: #0f5c54;
  --accent-deep: #0a413c;
  --accent-soft: #e4efec;
  --mark: #a8690a;
  --mark-soft: #fbf1dc;
  --alpha: #c0392b;
  --beta: #1d4f91;
  --gamma: #b8901a;
  --proton: #c0392b;
  --neutron: #2f7a4a;
  --electron: #2a62a8;
  --ion-plus: #d35400;
  --ok: #1f7a45;
  --ok-soft: #e6f5ea;
  --bad: #a32626;
  --bad-soft: #fbeaea;
  --lead: #2d3038;
  --al: #c5ccd4;
  --serif: Palatino, "Palatino Linotype", "Iowan Old Style", "Book Antiqua", Georgia, serif;
  --sans: "Avenir Next", "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: ui-monospace, Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html { font-size: 17px; }

html, body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
}

body { line-height: 1.5; }

a { color: var(--accent); }

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 1rem;
  align-items: center;
  padding: 0.55rem 1.2rem;
  background: var(--accent-deep);
  color: #f2ede2;
}

.brand {
  font-family: var(--serif);
  font-size: 1.02rem;
  font-weight: 600;
  text-decoration: none;
  color: inherit;
  line-height: 1.2;
}

.brand small {
  display: block;
  font-family: var(--sans);
  font-weight: 500;
  font-size: 0.72rem;
  opacity: 0.72;
}

.topbar nav {
  margin-left: auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0.15rem;
}

nav a {
  color: #f2ede2;
  text-decoration: none;
  font-size: 0.9rem;
  padding: 0.3rem 0.55rem;
  border-radius: 3px;
}

nav a[aria-current="page"] {
  background: rgba(255, 255, 255, 0.14);
  font-weight: 600;
}

nav a:hover { background: rgba(255, 255, 255, 0.1); }

/* ---------- page frame ---------- */

main {
  max-width: 880px;
  margin: 0 auto;
  padding: 1.6rem 1.2rem 4.5rem;
}

h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0 0 0.45rem;
  line-height: 1.2;
}

h1 { font-size: clamp(1.9rem, 3.2vw, 2.5rem); margin-bottom: 0.35rem; }
h2 { font-size: 1.45rem; }
h3 { font-size: 1.08rem; }

.kicker {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--mark);
  margin: 0 0 0.25rem;
}

.lede {
  color: var(--muted);
  font-size: 1.02rem;
  max-width: 44rem;
  margin: 0 0 1.4rem;
}

p { margin: 0.45rem 0; }

/* ---------- learning objectives (syllabus) ---------- */

.lo-block {
  margin: 0 0 2rem;
  padding: 0.85rem 1rem 0.95rem;
  background: var(--panel);
  border: 1px solid var(--rule);
  border-left: 4px solid var(--accent);
}

.lo-block h2 {
  font-family: var(--sans);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-deep);
  margin: 0 0 0.15rem;
}

.lo-stem {
  color: var(--muted);
  font-size: 0.92rem;
  margin: 0 0 0.45rem;
}

.lo-list {
  margin: 0;
  padding: 0 0 0 1.15rem;
  display: grid;
  gap: 0.3rem;
  font-size: 0.95rem;
}

.lo-list li { padding: 0; }

.lo-list li p {
  margin: 0;
  display: inline;
}

.lo-list li p + p.dse-labels {
  display: inline-flex;
  margin-left: 0.4rem;
  vertical-align: middle;
}

.lo-ext {
  display: inline-block;
  margin-left: 0.35rem;
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mark);
  font-weight: 700;
}

.dse-labels {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.22rem;
  margin: 0;
}

.dse-labels a,
.dse-chip {
  display: inline-block;
  text-decoration: none;
  color: var(--accent-deep);
  background: var(--accent-soft);
  border: 1px solid #c9d9d4;
  border-radius: 3px;
  font-size: 0.7rem;
  line-height: 1.3;
  padding: 0.03rem 0.34rem;
  font-variant-numeric: tabular-nums;
}

.dse-labels a:hover { border-color: var(--accent); background: #d5e9e4; }

/* ---------- chapter map / picker ---------- */

.toc, .chapter-cards {
  display: grid;
  gap: 0.7rem;
  margin: 0 0 2rem;
}

.toc a, .chapter-cards a {
  display: grid;
  grid-template-columns: 4.2rem 1fr;
  gap: 0 1rem;
  align-items: baseline;
  text-decoration: none;
  color: inherit;
  padding: 0.85rem 1rem;
  background: var(--panel);
  border: 1px solid var(--rule);
  border-radius: 4px;
}

.toc a:hover, .chapter-cards a:hover { border-color: var(--accent); }

.toc a .num, .chapter-cards a .num {
  font-family: var(--serif);
  font-size: 1.35rem;
  color: var(--accent-deep);
  font-variant-numeric: tabular-nums;
}

.toc a strong, .chapter-cards a strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.15rem;
  font-weight: 600;
}

.toc a span, .chapter-cards a span {
  display: block;
  grid-column: 2;
  color: var(--muted);
  font-size: 0.93rem;
  margin-top: 0.15rem;
}

/* ---------- sections ---------- */

.idea {
  margin: 2.4rem 0 0;
  padding-top: 1.4rem;
  border-top: 1px solid var(--rule);
}

.idea > header {
  display: flex;
  align-items: baseline;
  gap: 0.7rem;
  margin-bottom: 0.8rem;
}

.idea > header h2 { margin: 0; }

.sec-num {
  display: inline-block;
  min-width: 1.6rem;
  margin-right: 0.35rem;
  color: var(--mark);
  font-variant-numeric: tabular-nums;
}

.stamp {
  margin-left: auto;
  font-size: 0.78rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ---------- figures ---------- */

figure.fig {
  margin: 0.9rem 0 1rem;
}

figure.fig figcaption {
  margin-top: 0.4rem;
  font-size: 0.88rem;
  color: var(--muted);
}

figure.fig figcaption b {
  color: var(--ink);
  font-weight: 600;
}

.visual {
  background: var(--panel);
  border: 1px solid var(--rule);
  border-radius: 3px;
  padding: 0.5rem;
  overflow: hidden;
}

.visual svg,
.visual canvas {
  display: block;
  width: 100%;
  height: auto;
}

.visual.svg-fig { padding: 0.8rem 0.9rem; }

.stage {
  position: relative;
  overflow: hidden;
}

.visual.play.stage {
  --box-scale: 1;
  zoom: var(--box-scale);
}

@supports not (zoom: 1) {
  .visual.play.stage {
    transform: scale(var(--box-scale));
    transform-origin: top center;
  }
}

.box-scale {
  position: absolute;
  top: 0.4rem;
  right: 0.4rem;
  z-index: 6;
  display: inline-flex;
  gap: 0.2rem;
}

.box-scale button {
  width: 1.7rem;
  height: 1.7rem;
  padding: 0;
  border: 1px solid var(--rule);
  border-radius: 3px;
  background: rgba(255, 253, 248, 0.94);
  color: var(--muted);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.box-scale button:hover:not(:disabled) { color: var(--ink); border-color: var(--accent); }
.box-scale button:disabled { opacity: 0.3; cursor: default; }

.stage canvas.scene-canvas {
  display: block;
  width: 100%;
  height: 300px;
  background: var(--panel);
  cursor: grab;
  touch-action: none;
}

.stage canvas.scene-canvas:active { cursor: grabbing; }
.stage canvas.scene-canvas.tall { height: 400px; }

.stage .hud-label {
  position: absolute;
  font-size: 12px;
  color: var(--ink);
  pointer-events: none;
  white-space: nowrap;
  transform: translate(-50%, 0);
  text-shadow: 0 0 5px var(--panel), 0 0 5px var(--panel);
}

.pane-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.7rem;
}

.pane-pair .stage canvas.scene-canvas { height: 270px; }

@media (max-width: 720px) {
  .pane-pair { grid-template-columns: 1fr; }
}

.caption {
  margin: 0.4rem 0 0;
  font-size: 0.88rem;
  color: var(--muted);
}

/* ---------- controls: only real simulation controls remain ---------- */

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  margin: 0.55rem 0;
  font-size: 0.92rem;
}

.row > .row-label {
  color: var(--muted);
  font-size: 0.85rem;
  margin-right: 0.15rem;
}

button, .chip {
  font: inherit;
  font-size: 0.9rem;
  border: 1px solid #c3bfb4;
  border-radius: 3px;
  background: #fff;
  color: var(--ink);
  padding: 0.3rem 0.7rem;
  cursor: pointer;
}

button:hover { border-color: var(--accent); }

button[aria-pressed="true"],
.chip.on {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.readout {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.9rem;
  padding: 0.22rem 0.55rem;
  border: 1px solid var(--rule);
  border-radius: 3px;
  background: var(--panel);
}

input[type="range"] { accent-color: var(--accent); }

.legend {
  display: flex;
  gap: 0.9rem;
  flex-wrap: wrap;
  margin: 0.45rem 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.swatch {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  margin-right: 0.28rem;
  vertical-align: -0.05rem;
  border-radius: 50%;
}

.swatch.a { background: var(--alpha); }
.swatch.b { background: var(--beta); }
.swatch.g { background: var(--gamma); }
.swatch.p { background: var(--proton); }
.swatch.n { background: var(--neutron); }
.swatch.e { background: var(--electron); }

/* ---------- prose blocks ---------- */

.def, .tip, .worked, .eq {
  margin: 0.9rem 0;
}

.def {
  padding: 0.7rem 0.9rem;
  border: 1px solid var(--rule);
  border-left: 4px solid var(--accent);
  background: var(--panel);
}

.tip {
  padding: 0.65rem 0.9rem;
  background: var(--mark-soft);
  border-left: 4px solid var(--mark);
  font-size: 0.95rem;
}

.tag {
  display: inline-block;
  margin-right: 0.45rem;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent-deep);
}

.tip .tag { color: var(--mark); }

.def p, .tip p { margin: 0.25rem 0 0; }
.def p:first-child, .tip p:first-child { margin-top: 0; }

.eq {
  font-size: 1.08rem;
  padding: 0.35rem 0.9rem;
  border-left: 3px solid var(--rule);
  overflow-x: auto;
}

p.eq { font-family: var(--serif); }

.eq .katex-display,
.lo-block .katex-display { margin: 0.25rem 0; }

.eq .katex { font-size: 1.08em; }

.worked {
  padding: 0.75rem 0.95rem 0.85rem;
  border: 1px solid var(--rule);
  background: var(--panel);
}

.worked h3 {
  font-family: var(--sans);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent-deep);
  margin: 0 0 0.35rem;
}

.worked ol.steps {
  margin: 0.3rem 0 0;
  padding-left: 1.3rem;
}

.worked ol.steps li { margin: 0.2rem 0; }

.worked .eq { margin: 0.4rem 0; }

ul.points {
  margin: 0.6rem 0;
  padding-left: 1.2rem;
}

ul.points li { margin: 0.22rem 0; }

.later {
  margin: 1.4rem 0 0;
  padding: 0.6rem 0.85rem;
  border-left: 3px solid var(--rule);
  color: var(--muted);
  font-size: 0.93rem;
}

.next {
  margin: 2.6rem 0 0;
  padding-top: 1rem;
  border-top: 1px solid var(--rule);
  text-align: right;
}

/* ---------- tables ---------- */

table.compact, table.notes {
  border-collapse: collapse;
  width: max-content;
  max-width: 100%;
  table-layout: auto;
  font-size: 0.93rem;
  margin: 0.8rem 0;
}

table.compact th,
table.compact td,
table.notes th,
table.notes td {
  border: 1px solid var(--rule);
  padding: 0.38rem 0.6rem;
  text-align: center;
  vertical-align: top;
}

table.compact th, table.notes th {
  background: #efe9dc;
  font-weight: 600;
}

table.compact tbody th,
table.notes tbody th {
  background: #f6f1e6;
  text-align: left;
  font-weight: 600;
}

table.pair, table.notes {
  width: 100%;
}

table.pair th,
table.pair td,
table.notes th,
table.notes td { text-align: left; }

table.pair thead th:first-child:nth-last-child(2),
table.pair tbody td:first-child:nth-last-child(2) { width: 58%; }

table.pair thead th:last-child:nth-child(2),
table.pair tbody td:last-child:nth-child(2) { width: 42%; }

table.compact thead th:first-child:empty,
table.compact tbody td:first-child:nth-last-child(n + 3) {
  width: 1%;
  white-space: nowrap;
  text-align: left;
}

table.wide { width: 100%; }

table td.num, table th.num { text-align: right; font-variant-numeric: tabular-nums; }

/* spectrum bands table keeps the drawn proportions */

#spectrum table.spectrum-bands { width: 100%; table-layout: fixed; }

#spectrum table.spectrum-bands th {
  font-size: 0.78rem;
  padding: 0.3rem 0.2rem;
  word-break: break-word;
}

#spectrum table.spectrum-bands col.band-radio { width: 16%; }
#spectrum table.spectrum-bands col.band-micro { width: 14%; }
#spectrum table.spectrum-bands col.band-ir { width: 15%; }
#spectrum table.spectrum-bands col.band-vis { width: 6%; }
#spectrum table.spectrum-bands col.band-uv { width: 13%; }
#spectrum table.spectrum-bands col.band-xray { width: 17%; }
#spectrum table.spectrum-bands col.band-gamma { width: 19%; }

/* ---------- concept checks ---------- */

.check {
  margin: 1.3rem 0 0;
  padding: 0.85rem 1rem 0.95rem;
  border: 1px solid var(--rule);
  border-radius: 4px;
  background: var(--panel);
}

.check h3 {
  font-family: var(--sans);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent-deep);
  margin: 0 0 0.35rem;
}

.check h3 .src {
  margin-left: 0.5rem;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  color: var(--muted);
}

.check > p { margin: 0.3rem 0; }

.check .stem-list {
  margin: 0.3rem 0 0.5rem;
  padding-left: 1.4rem;
}

.check .stem-list li { margin: 0.12rem 0; }

.choices {
  display: grid;
  gap: 0.35rem;
  margin: 0.55rem 0 0;
}

.choices button {
  text-align: left;
  padding: 0.42rem 0.7rem 0.42rem 2.2rem;
  position: relative;
  background: #fff;
  line-height: 1.4;
}

.choices button::before {
  content: attr(data-choice);
  position: absolute;
  left: 0.7rem;
  top: 0.42rem;
  font-weight: 700;
  color: var(--muted);
}

.choices button:disabled { cursor: default; }

.choices button.correct {
  background: var(--ok-soft);
  border-color: var(--ok);
}

.choices button.correct::before { color: var(--ok); }

.choices button.wrong {
  background: var(--bad-soft);
  border-color: var(--bad);
}

.choices button.wrong::before { color: var(--bad); }

.tf-item {
  padding: 0.5rem 0 0.2rem;
  border-top: 1px dashed var(--rule-soft);
}

.tf-item:first-of-type { border-top: 0; padding-top: 0.2rem; }
.tf-item p { margin: 0.2rem 0; }
.tf-item .row { margin: 0.3rem 0; }

.tf-item button.correct { background: var(--ok-soft); border-color: var(--ok); }
.tf-item button.wrong { background: var(--bad-soft); border-color: var(--bad); }

.feedback {
  margin: 0.5rem 0 0;
  font-size: 0.93rem;
  font-weight: 600;
}

.feedback:empty { display: none; }
.feedback.ok { color: var(--ok); }
.feedback.no { color: var(--bad); }

