// Element clips from a notes page via CDP.
// Usage: node /tmp/p2n-clip.mjs <outDir> <url> <prefix> <selector>[|<maxHeight>] ...
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";
import { createServer } from "node:net";

const [outDir, url, prefix, ...selectors] = process.argv.slice(2);
const chromePath = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
fs.mkdirSync(outDir, { recursive: true });

async function freePort() {
  return new Promise((resolve, reject) => {
    const s = createServer();
    s.listen(0, "127.0.0.1", () => { const { port } = s.address(); s.close((e) => (e ? reject(e) : resolve(port))); });
    s.on("error", reject);
  });
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const profile = fs.mkdtempSync(path.join(os.tmpdir(), "p2n-clip-"));
const port = await freePort();
const chrome = spawn(chromePath, [
  "--headless=new", "--use-angle=swiftshader", "--no-first-run", "--no-default-browser-check",
  "--disable-extensions", "--disable-background-timer-throttling", "--disable-renderer-backgrounding",
  "--remote-debugging-port=" + port, "--user-data-dir=" + profile, "--window-size=1280,900", "about:blank"
], { stdio: "ignore" });

let target;
for (let i = 0; i < 100 && !target; i++) {
  try {
    const list = await (await fetch("http://127.0.0.1:" + port + "/json/list")).json();
    target = list.find((t) => t.type === "page" && t.webSocketDebuggerUrl);
  } catch (_) { /* not ready */ }
  if (!target) await sleep(100);
}
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0; const pending = new Map();
ws.addEventListener("message", (ev) => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result.value;

await send("Page.enable"); await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1100, height: 900, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: url + (url.includes("?") ? "&" : "?") + "_=" + Date.now() });
await sleep(3000);

for (const spec of selectors) {
  const [sel, maxH] = spec.split("|");
  const box = await evaluate(`(function () {
    var el = document.querySelector(${JSON.stringify(sel)});
    if (!el) return null;
    el.scrollIntoView({ block: "start" });
    window.scrollBy(0, -12);
    var r = el.getBoundingClientRect();
    return { x: r.left, y: r.top + window.scrollY, w: r.width, h: r.height, sy: window.scrollY };
  })()`);
  if (!box) { console.log("missing", sel); continue; }
  await sleep(500);
  const h = Math.min(box.h, Number(maxH || 1600));
  await send("Emulation.setDeviceMetricsOverride", { width: 1100, height: Math.ceil(h + 40), deviceScaleFactor: 1, mobile: false });
  await evaluate(`window.scrollTo(0, ${box.y - 12}); 1`);
  await sleep(400);
  const shot = await send("Page.captureScreenshot", { format: "png", clip: { x: Math.max(0, box.x - 8), y: 12, width: Math.min(box.w + 16, 1100), height: h, scale: 1 } });
  const name = prefix + "-" + sel.replace(/[^a-z0-9]+/gi, "_").replace(/^_+|_+$/g, "") + ".png";
  fs.writeFileSync(path.join(outDir, name), Buffer.from(shot.result.data, "base64"));
  console.log(name, Math.round(box.w) + "x" + Math.round(h));
  await send("Emulation.setDeviceMetricsOverride", { width: 1100, height: 900, deviceScaleFactor: 1, mobile: false });
}
ws.close(); chrome.kill("SIGKILL"); await sleep(200);
fs.rmSync(profile, { recursive: true, force: true });
